  {
    id: 'accent-color',
    tab: 'project',
    label: 'Accent Theme Color',
    keywords: ['accent', 'color', 'colour', 'theme', 'brand'],
    elementId: 'project-accent-color-input',
  },
  {
    id: 'visibility',
    tab: 'project',
    label: 'Hide Project from Active List',
    keywords: ['hide', 'archive', 'visible', 'show'],
