    tab: 'project',
    label: 'Max transient retries',
    keywords: ['retry', 'retries', 'transient', 'infrastructure', 'timeout', 'budget'],
    elementId: 'project-retry-max-transient-retries',
  },
  {
    id: 'auto-iteration',
    tab: 'project',
